        return "";
    }
    int len = str.length();
    if(start < 0){
        start = 0;
    }
    if(end < 0){
        end = 0;
    }
    if(start > len){
        start = len;
    }
    if(end > len){
        end = len;
    }
    if(start > end){
        return "";
    }
    try{
        return str.substring(start, end);
    }catch(Exception e){
        return "";
    }
}

